"""matplotlib.backend_bases — base backend classes.

The plotly backend doesn't drive Agg/Cairo/PDF directly, so these
classes are mostly state holders. We give every setter a real
implementation that stores its argument on the instance, so any code
that reads back the value via a getter (or copies a GC via
``copy_properties``) gets the expected state — which is most of what
upstream's own RendererBase / GraphicsContextBase guarantee anyway.
"""


class RendererBase:
    """Base renderer — concrete backends override draw_path/draw_text/
    draw_image. The base class still implements the
    ``open_group``/``close_group`` SVG-style call pair, points→pixels
    conversion using the current dpi, and ``new_gc`` factory."""

    def __init__(self):
        self._dpi = 72.0

    def draw_path(self, gc, path, transform, rgbFace=None):
        """No-op base — concrete backends draw the path. Stored for
        subclasses to inspect via :meth:`get_last_drawn`."""
        self._last_path = (gc, path, transform, rgbFace)

    def draw_image(self, gc, x, y, im, transform=None):
        self._last_image = (gc, x, y, im, transform)

    def draw_text(self, gc, x, y, s, prop, angle, ismath=False, mtext=None):
        self._last_text = (gc, x, y, s, prop, angle, ismath, mtext)

    def get_text_width_height_descent(self, s, prop, ismath):
        """Estimate text bounds from the font property + character count.
        Real Agg uses FreeType for exact measurements; we approximate
        using prop.get_size() and 0.6 em per character."""
        try:
            size = prop.get_size_in_points() if hasattr(prop, 'get_size_in_points') \
                   else prop.get_size()
        except Exception:
            size = 12.0
        char_w = size * 0.6
        return (char_w * max(len(s), 1), size * 1.2, size * 0.2)

    def points_to_pixels(self, points):
        """Convert font-points to pixels at the current dpi (72 pt/inch)."""
        return points * self._dpi / 72.0

    def get_canvas_width_height(self):
        return (640, 480)

    def new_gc(self):
        return GraphicsContextBase()

    def open_group(self, s, gid=None):
        self._last_group = (s, gid)

    def close_group(self, s):
        self._last_group_close = s

    def flipy(self):
        """Most backends count y-pixels from the top (True); a few
        backends — and the plotly backend — count from the bottom."""
        return False


class GraphicsContextBase:
    """Per-call graphics state (color, line width, dashes, hatch, clip,
    alpha). All setters store the value so downstream getters can
    inspect them; ``copy_properties`` does a full state copy."""

    def __init__(self):
        self._foreground = (0.0, 0.0, 0.0, 1.0)
        self._linewidth = 1.0
        self._linestyle = '-'
        self._capstyle = 'butt'
        self._joinstyle = 'round'
        self._dashes = (0, None)
        self._alpha = None
        self._clip_rectangle = None
        self._clip_path = None
        self._antialiased = True
        self._hatch = None
        self._gid = None
        self._url = None
        self._snap = None
        self._sketch = None

    def set_foreground(self, fg, isRGBA=False):
        if isRGBA:
            self._foreground = tuple(fg)
        else:
            try:
                from matplotlib.colors import to_rgba
                self._foreground = to_rgba(fg)
            except Exception:
                self._foreground = (0, 0, 0, 1)

    def get_foreground(self):
        return self._foreground

    def set_graylevel(self, frac):
        f = float(frac)
        self._foreground = (f, f, f, 1.0)

    def set_linewidth(self, w):       self._linewidth = float(w)
    def get_linewidth(self):          return self._linewidth

    def set_linestyle(self, style):   self._linestyle = style
    def get_linestyle(self):          return self._linestyle

    def set_capstyle(self, cs):       self._capstyle = cs
    def get_capstyle(self):           return self._capstyle

    def set_joinstyle(self, js):      self._joinstyle = js
    def get_joinstyle(self):          return self._joinstyle

    def set_dashes(self, dash_offset, dash_list):
        self._dashes = (dash_offset, dash_list)
    def get_dashes(self):             return self._dashes

    def set_alpha(self, alpha):       self._alpha = alpha
    def get_alpha(self):              return self._alpha

    def set_clip_rectangle(self, rectangle):  self._clip_rectangle = rectangle
    def get_clip_rectangle(self):     return self._clip_rectangle

    def set_clip_path(self, path):    self._clip_path = path
    def get_clip_path(self):          return self._clip_path

    def set_antialiased(self, b):     self._antialiased = bool(b)
    def get_antialiased(self):        return self._antialiased

    def set_hatch(self, hatch):       self._hatch = hatch
    def get_hatch(self):              return self._hatch

    def set_gid(self, gid):           self._gid = gid
    def get_gid(self):                return self._gid

    def set_url(self, url):           self._url = url
    def get_url(self):                return self._url

    def set_snap(self, snap):         self._snap = snap
    def get_snap(self):               return self._snap

    def set_sketch_params(self, scale=None, length=None, randomness=None):
        self._sketch = (scale, length, randomness)
    def get_sketch_params(self):      return self._sketch

    def get_rgb(self):
        return self._foreground

    def restore(self):
        """No-op in the base — concrete backends pop their saved state."""
        pass

    def copy_properties(self, gc):
        """Copy every state attribute from ``gc`` onto self."""
        for attr in ('_foreground', '_linewidth', '_linestyle', '_capstyle',
                      '_joinstyle', '_dashes', '_alpha', '_clip_rectangle',
                      '_clip_path', '_antialiased', '_hatch', '_gid',
                      '_url', '_snap', '_sketch'):
            if hasattr(gc, attr):
                setattr(self, attr, getattr(gc, attr))


class FigureCanvasBase:
    """Canvas the figure draws onto. The plotly backend doesn't have a
    pixel buffer, but we still expose the standard event-connect API
    so user code can register handlers."""

    def __init__(self, figure=None):
        self.figure = figure
        self._callbacks = {}      # event_name → [callbacks]
        self._cid_counter = 0
        self._cid_to_event = {}   # cid → event_name (for disconnect)

    def draw(self):
        """Trigger a redraw. Plotly handles this autonomously, so the
        base call is a no-op — but we still update the figure's stale
        flag so user code that polls it sees the right state."""
        if self.figure is not None:
            try: self.figure.stale = False
            except Exception: pass

    def draw_idle(self):
        self.draw()

    def blit(self, bbox=None):
        """Repaint just the region inside ``bbox``. Plotly always
        repaints the whole figure, so we delegate to draw()."""
        self.draw()

    def resize(self, w, h):
        if self.figure is not None and hasattr(self.figure, 'set_size_inches'):
            try:
                self.figure.set_size_inches(w / 100.0, h / 100.0)
            except Exception:
                pass

    def get_width_height(self, *, physical=False):
        if self.figure is None:
            return (640, 480)
        try:
            w_in, h_in = self.figure.get_size_inches()
            dpi = self.figure.get_dpi() if hasattr(self.figure, 'get_dpi') else 100
            return (int(w_in * dpi), int(h_in * dpi))
        except Exception:
            return (640, 480)

    def print_figure(self, filename, **kwargs):
        """Delegate to the figure's savefig (mirrors upstream — the
        canvas is the entry point but Figure.savefig does the work)."""
        if self.figure is not None and hasattr(self.figure, 'savefig'):
            return self.figure.savefig(filename, **kwargs)
        return None

    def get_default_filetype(self):
        return 'png'

    def get_supported_filetypes(self):
        return {
            'png':  'Portable Network Graphics',
            'pdf':  'Portable Document Format',
            'svg':  'Scalable Vector Graphics',
            'jpg':  'JPEG',
            'jpeg': 'JPEG',
            'html': 'HyperText Markup Language (Plotly)',
            'webp': 'WebP',
        }

    def get_supported_filetypes_grouped(self):
        return {
            'Portable Network Graphics':  ['png'],
            'Portable Document Format':   ['pdf'],
            'Scalable Vector Graphics':   ['svg'],
            'JPEG':                       ['jpg', 'jpeg'],
            'HyperText Markup Language':  ['html'],
            'WebP':                       ['webp'],
        }

    def mpl_connect(self, s, func):
        """Register ``func`` for event ``s``. Returns an opaque cid."""
        self._cid_counter += 1
        cid = self._cid_counter
        self._callbacks.setdefault(s, []).append((cid, func))
        self._cid_to_event[cid] = s
        return cid

    def mpl_disconnect(self, cid):
        s = self._cid_to_event.pop(cid, None)
        if s is None:
            return
        self._callbacks[s] = [(c, f) for c, f in self._callbacks.get(s, [])
                                if c != cid]

    def callbacks_process(self, event_name, event):
        """Invoke every registered callback for ``event_name``."""
        for cid, fn in self._callbacks.get(event_name, []):
            try: fn(event)
            except Exception: pass

    def flush_events(self):
        pass

    def start_event_loop(self, timeout=0):
        pass

    def stop_event_loop(self):
        pass


class FigureManagerBase:
    """Wraps a canvas + window state. The plotly backend doesn't have
    a real window, but we track title/size so introspection works."""

    def __init__(self, canvas, num):
        self.canvas = canvas
        self.num = num
        self._window_title = ''
        self._fullscreen = False
        self._size = (640, 480)

    def show(self):
        if self.canvas is not None and hasattr(self.canvas, 'figure'):
            try:
                from matplotlib import pyplot as _plt
                _plt.show()
            except Exception:
                pass

    def destroy(self):
        try:
            from matplotlib._pylab_helpers import Gcf
            Gcf.destroy(self.num)
        except Exception:
            pass

    def full_screen_toggle(self):
        self._fullscreen = not self._fullscreen

    def resize(self, w, h):
        self._size = (int(w), int(h))
        if self.canvas is not None:
            self.canvas.resize(w, h)

    def set_window_title(self, title):
        self._window_title = '' if title is None else str(title)

    def get_window_title(self):
        return self._window_title


