class ShowBase:
    """Base for Backend ``Show`` classes — implements ``__call__`` which
    upstream uses to dispatch ``plt.show()`` through the active backend.
    """
    def __call__(self, block=None, **kwargs):
        return self.mainloop()

    def mainloop(self):
        pass


class TimerBase:
    """Base for backend timer objects. Subclasses wire ``_timer_start``
    etc to their underlying GUI toolkit; this base offers the API."""

    def __init__(self, interval=None, callbacks=None):
        self.interval = interval if interval is not None else 1000
        self.callbacks = list(callbacks) if callbacks else []
        self._single = False
        self._running = False

    def start(self, interval=None):
        if interval is not None:
            self.interval = interval
        self._running = True

    def stop(self):
        self._running = False

    def add_callback(self, func, *args, **kwargs):
        self.callbacks.append((func, args, kwargs))

    def remove_callback(self, func, *args, **kwargs):
        # Match-by-callable; drop the first matching registration.
        for i, (f, a, k) in enumerate(self.callbacks):
            if f is func and (not args or a == args) and (not kwargs or k == kwargs):
                del self.callbacks[i]
                return

    def _on_timer(self):
        # Invoke all callbacks; if any returns False, drop it.
        survivors = []
        for f, a, k in self.callbacks:
            try:
                if f(*a, **k) is not False:
                    survivors.append((f, a, k))
            except Exception:
                survivors.append((f, a, k))
        self.callbacks = survivors


class Cursors:
    """Cursor-shape enum used by ``NavigationToolbar2.set_cursor``."""
    HAND, POINTER, SELECT_REGION, MOVE, WAIT, RESIZE_HORIZONTAL, RESIZE_VERTICAL = range(7)


class GraphicsContextRenderer(GraphicsContextBase):
    """Convenience subclass that bundles a graphics context with a
    renderer — upstream uses this in some backends as the ``new_gc``
    return type."""
    def __init__(self, renderer=None):
        self.renderer = renderer


class _Backend:
    """Tiny holder mirroring upstream's ``_Backend`` namespace. Backends
    set ``FigureCanvas`` and ``FigureManager`` attributes on a subclass
    to register themselves."""
    FigureCanvas = FigureCanvasBase
    FigureManager = FigureManagerBase
    backend_version = '0.0'

    @classmethod
    def new_figure_manager(cls, num, *args, **kwargs):
        from matplotlib.figure import Figure
        fig = Figure(*args, **kwargs)
        canvas = cls.FigureCanvas(fig)
        return cls.FigureManager(canvas, num)

    @classmethod
    def show(cls, *, block=None):
        pass

    @classmethod
    def draw_if_interactive(cls):
        pass


def register_backend(name, module_name, description=None):
    """Stub matching upstream's signature — backend registration is a
    no-op in the shim since pyplot always uses the plotly backend."""
    return None


def get_registered_canvas_class(format):
    return FigureCanvasBase


