class NonGuiException(Exception):
    """Raised when GUI-only functionality is requested in a non-GUI
    backend. The shim never raises it but exposes the class for
    isinstance checks."""
    pass


# Lowercase alias used by some upstream code — same as Cursors above.
cursors = Cursors


def button_press_handler(event, canvas=None, toolbar=None):
    """Default ``button_press_event`` handler. Mirrors upstream's
    keyboard-style ('pan', 'zoom', 'home') handling — we just record the
    event on the canvas for any user listeners."""
    if canvas is not None and hasattr(canvas, '_callbacks'):
        for cb in canvas._callbacks.get('button_press_event', []):
            try: cb(event)
            except Exception: pass


def key_press_handler(event, canvas=None, toolbar=None):
    """Default ``key_press_event`` handler. Honours the standard
    matplotlib shortcuts (g for grid, l for log scale, etc.) — but
    since the plotly backend has no canvas, we just dispatch user
    callbacks."""
    if canvas is not None and hasattr(canvas, '_callbacks'):
        for cb in canvas._callbacks.get('key_press_event', []):
            try: cb(event)
            except Exception: pass


