def _attach_gc_methods(cls):
    def get_alpha(self):              return getattr(self, '_alpha', 1.0)
    def get_antialiased(self):        return getattr(self, '_aa', True)
    def get_capstyle(self):           return getattr(self, '_capstyle', 'butt')
    def get_clip_path(self):          return getattr(self, '_clip_path', None)
    def get_clip_rectangle(self):     return getattr(self, '_clip_rect', None)
    def get_dashes(self):             return getattr(self, '_dashes', (None, None))
    def get_forced_alpha(self):       return getattr(self, '_forced_alpha', False)
    def get_gid(self):                return getattr(self, '_gid', None)
    def get_hatch(self):              return getattr(self, '_hatch', None)
    def get_hatch_color(self):        return getattr(self, '_hatch_color', (0, 0, 0, 1))
    def get_hatch_linewidth(self):    return getattr(self, '_hatch_lw', 1.0)
    def get_hatch_path(self, density=6.0): return None
    def get_joinstyle(self):          return getattr(self, '_joinstyle', 'round')
    def get_linestyle(self):          return getattr(self, '_linestyle', '-')
    def get_sketch_params(self):      return getattr(self, '_sketch', None)
    def get_snap(self):               return getattr(self, '_snap', None)
    def get_url(self):                return getattr(self, '_url', None)
    def set_forced_alpha(self, b):    self._forced_alpha = bool(b)
    def set_gid(self, gid):           self._gid = gid
    def set_sketch_params(self, scale=None, length=None, randomness=None):
        self._sketch = (scale, length, randomness)
    def set_snap(self, snap):         self._snap = snap
    def set_url(self, url):           self._url = url
    cls.get_alpha = get_alpha; cls.get_antialiased = get_antialiased
    cls.get_capstyle = get_capstyle; cls.get_clip_path = get_clip_path
    cls.get_clip_rectangle = get_clip_rectangle; cls.get_dashes = get_dashes
    cls.get_forced_alpha = get_forced_alpha; cls.get_gid = get_gid
    cls.get_hatch = get_hatch; cls.get_hatch_color = get_hatch_color
    cls.get_hatch_linewidth = get_hatch_linewidth
    cls.get_hatch_path = get_hatch_path
    cls.get_joinstyle = get_joinstyle; cls.get_linestyle = get_linestyle
    cls.get_sketch_params = get_sketch_params; cls.get_snap = get_snap
    cls.get_url = get_url
    cls.set_forced_alpha = set_forced_alpha; cls.set_gid = set_gid
    cls.set_sketch_params = set_sketch_params
    cls.set_snap = set_snap; cls.set_url = set_url

_attach_gc_methods(GraphicsContextBase)


def _attach_canvas_methods(cls):
    cls.button_pick_id = 0
    cls.callbacks = property(lambda self: getattr(self, '_callbacks', {}))
    cls.device_pixel_ratio = property(lambda self: 1.0)
    cls.events = ['button_press_event', 'button_release_event',
                   'motion_notify_event', 'key_press_event', 'key_release_event',
                   'pick_event', 'resize_event', 'figure_enter_event',
                   'figure_leave_event', 'close_event', 'scroll_event',
                   'draw_event']
    cls.filetypes = {'png': 'PNG', 'pdf': 'PDF', 'svg': 'SVG',
                      'jpg': 'JPEG', 'jpeg': 'JPEG', 'webp': 'WebP',
                      'html': 'HTML', 'json': 'JSON'}
    cls.fixed_dpi = None
    cls.required_interactive_framework = None

    def copy_from_bbox(self, bbox): return None
    def enter_notify_event(self, *args, **kwargs): pass
    def grab_mouse(self, ax): pass
    def inaxes(self, xy):           return None
    def is_saving(self):             return False
    def key_press_event(self, key, *args, **kwargs): pass
    def key_release_event(self, key, *args, **kwargs): pass
    def leave_notify_event(self, *args, **kwargs): pass
    def manager(self):               return None
    def motion_notify_event(self, x, y, *args, **kwargs): pass
    def new_timer(self, interval=None, callbacks=None):
        return TimerBase(interval=interval, callbacks=callbacks)
    def pick(self, mouseevent): pass
    def release_mouse(self, ax): pass
    def restore_region(self, region, bbox=None, xy=None): pass
    def scroll_event(self, x, y, step, *args, **kwargs): pass
    def set_window_title(self, title): pass
    def switch_backends(self, FigureCanvasClass):
        return FigureCanvasClass(self.figure)

    cls.copy_from_bbox = copy_from_bbox; cls.enter_notify_event = enter_notify_event
    cls.grab_mouse = grab_mouse; cls.inaxes = inaxes; cls.is_saving = is_saving
    cls.key_press_event = key_press_event; cls.key_release_event = key_release_event
    cls.leave_notify_event = leave_notify_event
    cls.motion_notify_event = motion_notify_event
    cls.new_timer = new_timer; cls.pick = pick; cls.release_mouse = release_mouse
    cls.restore_region = restore_region; cls.scroll_event = scroll_event
    cls.set_window_title = set_window_title
    cls.switch_backends = switch_backends

